await consumer.run({
  eachBatch: async ({ batch, resolveOffset, heartbeat }) => {
    for (const m of batch.messages) {
      const g = groups.get(m.headers['seq-id']) ?? newGroup(m.headers['size']);
      g.parts[m.headers['pos'] - 1] = m.value;
      if (g.parts.every(Boolean)) { await deliver(g); groups.delete(g.id); }
      resolveOffset(m.offset);        // commit only after the group is out
    }
    await heartbeat();
  },
});
